"use client";

import { useEffect, useState } from "react";
import guideData from "@/lib/exercise-guide.json";
import { VIDEOS } from "@/lib/exercise-videos";

// Generated by scripts/build-exercise-guide.mjs from free-exercise-db (public domain).
type GuideEntry = {
  source: string;
  equipment: string | null;
  level: string;
  primaryMuscles: string[];
  secondaryMuscles: string[];
  instructions: string[];
  images: string[];
  note?: string;
};
const GUIDE = guideData as Record<string, GuideEntry>;

export const hasGuide = (exercise: string) =>
  exercise in GUIDE || exercise in VIDEOS;

const FRAME_MS = 1100;

/** Full-screen "How to": start/end photos alternating like a short clip, muscles and steps. */
export function ExerciseGuide({
  exercise,
  onClose,
}: {
  exercise: string;
  onClose: () => void;
}) {
  const g = GUIDE[exercise];
  const videos = VIDEOS[exercise] ?? [];
  const [videoIdx, setVideoIdx] = useState(0);
  const video = videos[videoIdx];
  const [frame, setFrame] = useState(0);
  const [playing, setPlaying] = useState(!video);
  const [showVideo, setShowVideo] = useState(false);

  useEffect(() => {
    document.body.style.overflow = "hidden";
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", onKey);
    return () => {
      document.body.style.overflow = "";
      window.removeEventListener("keydown", onKey);
    };
  }, [onClose]);

  useEffect(() => {
    if (!playing || !g || g.images.length < 2) return;
    const id = setInterval(
      () => setFrame((f) => (f + 1) % g.images.length),
      FRAME_MS,
    );
    return () => clearInterval(id);
  }, [playing, g]);

  if (!g && !video) return null;
  const images = g?.images ?? [];
  const frameLabel =
    frame === 0
      ? "Start"
      : frame === images.length - 1
        ? "End"
        : `Step ${frame + 1}`;

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-label={`How to: ${exercise}`}
      className="fixed inset-0 z-[60] overflow-y-auto bg-zinc-950"
    >
      <div className="mx-auto w-full max-w-md px-4 pb-10">
        <div className="sticky top-0 z-10 -mx-4 flex items-center justify-between gap-3 bg-zinc-950/95 px-4 py-3 backdrop-blur">
          <div className="min-w-0">
            <p className="text-[11px] font-semibold uppercase tracking-wider text-lime-300">
              How to
            </p>
            <p className="truncate font-semibold">{exercise}</p>
          </div>
          <button
            type="button"
            onClick={onClose}
            aria-label="Close"
            className="grid h-9 w-9 shrink-0 place-items-center rounded-full bg-zinc-800 text-lg text-zinc-200 hover:bg-zinc-700"
          >
            ×
          </button>
        </div>

        {video && (
          <div className="mt-1 overflow-hidden rounded-2xl bg-zinc-900">
            {showVideo ? (
              <iframe
                src={`https://www.youtube-nocookie.com/embed/${video.id}?autoplay=1&playsinline=1&rel=0${video.start ? `&start=${video.start}` : ""}`}
                title={`${exercise} demo video`}
                allow="autoplay; encrypted-media; picture-in-picture; fullscreen"
                allowFullScreen
                className="aspect-video w-full"
              />
            ) : (
              <button
                type="button"
                onClick={() => {
                  setPlaying(false);
                  setShowVideo(true);
                }}
                className="grid aspect-video w-full place-items-center bg-gradient-to-br from-zinc-800 to-zinc-900 text-zinc-100"
              >
                <span className="grid place-items-center gap-2">
                  <span className="grid h-14 w-14 place-items-center rounded-full bg-red-600 text-2xl">
                    ▶
                  </span>
                  <span className="text-sm font-semibold">
                    Watch demo video
                  </span>
                  <span className="text-xs text-zinc-400">
                    Plays from YouTube
                    {video.start
                      ? ` at ${Math.floor(video.start / 60)}:${String(video.start % 60).padStart(2, "0")}`
                      : ""}
                  </span>
                </span>
              </button>
            )}
          </div>
        )}
        {videos.length > 1 && (
          <div className="mt-2 grid grid-cols-2 gap-2">
            {videos.map((v, i) => (
              <button
                key={v.id}
                type="button"
                onClick={() => setVideoIdx(i)}
                aria-pressed={videoIdx === i}
                className={`h-9 rounded-lg text-sm font-semibold transition ${
                  videoIdx === i
                    ? "bg-zinc-100 text-zinc-900"
                    : "bg-zinc-800 text-zinc-300 hover:bg-zinc-700"
                }`}
              >
                Video {i + 1}
              </button>
            ))}
          </div>
        )}
        {video && (
          <a
            href={`https://www.youtube.com/watch?v=${video.id}${video.start ? `&t=${video.start}s` : ""}`}
            target="_blank"
            rel="noopener noreferrer"
            className="mt-2 inline-block text-xs font-semibold text-zinc-400 underline hover:text-zinc-200"
          >
            Open in YouTube
          </a>
        )}

        {g && g.images.length > 0 && (
          <button
            type="button"
            onClick={() => setPlaying((p) => !p)}
            aria-label={playing ? "Pause demo" : "Play demo"}
            className="relative mt-1 block w-full overflow-hidden rounded-2xl bg-zinc-900"
          >
            {g.images.map((src, i) => (
              // eslint-disable-next-line @next/next/no-img-element
              <img
                key={src}
                src={src}
                alt={`${exercise} — ${i === 0 ? "start" : "end"} position`}
                className={`w-full object-cover transition-opacity duration-300 ${i === 0 ? "relative" : "absolute inset-0 h-full"} ${
                  i === frame ? "opacity-100" : "opacity-0"
                }`}
              />
            ))}
            <span className="absolute left-2 top-2 rounded-full bg-zinc-950/80 px-2.5 py-1 text-xs font-semibold text-zinc-100">
              {frameLabel}
            </span>
            <span className="absolute bottom-2 right-2 rounded-full bg-zinc-950/80 px-2.5 py-1 text-xs font-semibold text-zinc-100">
              {playing ? "❚❚ Pause" : "▶ Play"}
            </span>
          </button>
        )}
        {g && g.images.length > 1 && (
          <div className="mt-2 grid grid-cols-2 gap-2">
            {g.images.map((src, i) => (
              <button
                key={src}
                type="button"
                onClick={() => {
                  setPlaying(false);
                  setFrame(i);
                }}
                aria-pressed={frame === i && !playing}
                className={`h-9 rounded-lg text-sm font-semibold transition ${
                  frame === i
                    ? "bg-zinc-100 text-zinc-900"
                    : "bg-zinc-800 text-zinc-300 hover:bg-zinc-700"
                }`}
              >
                {i === 0
                  ? "Start"
                  : i === g.images.length - 1
                    ? "End"
                    : `Step ${i + 1}`}
              </button>
            ))}
          </div>
        )}

        {g && (
          <>
            <div className="mt-4 flex flex-wrap gap-1.5">
              {g.primaryMuscles.map((m) => (
                <span
                  key={m}
                  className="rounded-full bg-lime-400/15 px-2.5 py-1 text-xs font-semibold capitalize text-lime-200"
                >
                  {m}
                </span>
              ))}
              {g.secondaryMuscles.map((m) => (
                <span
                  key={m}
                  className="rounded-full bg-zinc-800 px-2.5 py-1 text-xs capitalize text-zinc-400"
                >
                  {m}
                </span>
              ))}
            </div>

            {g.note && (
              <p className="mt-4 rounded-xl border border-amber-400/30 bg-amber-400/10 px-3.5 py-2.5 text-sm text-amber-100">
                {g.note}
              </p>
            )}

            <ol className="mt-4 grid gap-3">
              {g.instructions.map((step, i) => (
                <li
                  key={i}
                  className="flex gap-3 text-sm leading-relaxed text-zinc-200"
                >
                  <span className="grid h-6 w-6 shrink-0 place-items-center rounded-full bg-zinc-800 text-xs font-bold text-zinc-300">
                    {i + 1}
                  </span>
                  <span>{step}</span>
                </li>
              ))}
            </ol>

            <p className="mt-6 text-xs text-zinc-500">
              {g.source !== exercise && <>Shown as “{g.source}”. </>}
              Photos and steps from free-exercise-db (public domain). Your
              card&apos;s cue and the program&apos;s sets, reps and rest still
              apply.
            </p>
          </>
        )}
        {!g && (
          <p className="mt-4 text-xs text-zinc-500">
            Video hosted on YouTube. Your card&apos;s cue and the program&apos;s
            sets, reps and rest still apply.
          </p>
        )}

        <button
          type="button"
          onClick={onClose}
          className="mt-5 h-12 w-full rounded-xl bg-zinc-800 text-base font-semibold text-zinc-100 transition hover:bg-zinc-700 active:scale-[0.98]"
        >
          Back to workout
        </button>
      </div>
    </div>
  );
}
